-- lovable-cron-fallback-reviewed: Wake on enqueue and disarm after drain; one-minute retries survive browser disconnect with no permanent idle sweeper.
ALTER TABLE public.chat_jobs ADD COLUMN IF NOT EXISTS visual_required boolean;
ALTER TABLE public.browser_checks ADD COLUMN IF NOT EXISTS visual_phase text NOT NULL DEFAULT 'inspection', ADD COLUMN IF NOT EXISTS capture_status text NOT NULL DEFAULT 'pending', ADD COLUMN IF NOT EXISTS inspection_status text NOT NULL DEFAULT 'pending';
CREATE TABLE public.site_ai_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),project_id uuid NOT NULL REFERENCES public.projects(id) ON DELETE CASCADE,user_id uuid NOT NULL,request_key text NOT NULL,messages jsonb NOT NULL,model text NOT NULL,status text NOT NULL DEFAULT 'queued',reply text NOT NULL DEFAULT '',error text,key_position integer NOT NULL DEFAULT 0,key_attempt integer NOT NULL DEFAULT 0,attempt_serial integer NOT NULL DEFAULT 0,provider_id text,reserved integer NOT NULL DEFAULT 0,usage_day date NOT NULL DEFAULT (now() AT TIME ZONE 'UTC')::date,next_attempt_at timestamptz NOT NULL DEFAULT now(),lease_until timestamptz,lease_version integer NOT NULL DEFAULT 0,deadline timestamptz NOT NULL DEFAULT now()+interval '24 hours',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(project_id,request_key));
GRANT ALL ON public.site_ai_requests TO service_role;
ALTER TABLE public.site_ai_requests ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.site_ai_key_state(provider_id text NOT NULL,day date NOT NULL,cooldown_until timestamptz,PRIMARY KEY(provider_id,day));
GRANT ALL ON public.site_ai_key_state TO service_role;
ALTER TABLE public.site_ai_key_state ENABLE ROW LEVEL SECURITY;
CREATE INDEX site_ai_requests_due ON public.site_ai_requests(status,next_attempt_at);
CREATE FUNCTION public.admit_site_ai(_project uuid,_user uuid,_key text,_messages jsonb,_model text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s public.project_ai_settings;r public.site_ai_requests;d date:=(now() AT TIME ZONE 'UTC')::date;n uuid; BEGIN SELECT * INTO s FROM public.project_ai_settings WHERE project_id=_project AND user_id=_user FOR UPDATE; IF s.project_id IS NULL OR NOT s.cloudflare_enabled THEN RAISE EXCEPTION 'AI is off for this site';END IF; IF NOT EXISTS(SELECT 1 FROM public.ai_pool_settings WHERE id='global' AND cloudflare_pool_enabled) THEN RAISE EXCEPTION 'Cloudflare pool is off';END IF;SELECT * INTO r FROM public.site_ai_requests WHERE project_id=_project AND request_key=_key;IF r.id IS NOT NULL THEN IF r.messages<>_messages THEN RAISE EXCEPTION 'Request identity already used for different input';END IF;RETURN r.id;END IF;IF s.usage_day=d AND s.day_requests>=500 THEN RAISE EXCEPTION 'Daily AI limit reached';END IF;UPDATE public.project_ai_settings SET usage_day=d,day_requests=CASE WHEN usage_day=d THEN day_requests+1 ELSE 1 END WHERE project_id=_project;INSERT INTO public.site_ai_requests(project_id,user_id,request_key,messages,model) VALUES(_project,_user,_key,_messages,_model) RETURNING id INTO n;RETURN n;END $$;
CREATE FUNCTION public.claim_site_ai(_id uuid) RETURNS SETOF public.site_ai_requests LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.site_ai_requests;BEGIN SELECT * INTO r FROM public.site_ai_requests WHERE id=_id FOR UPDATE;IF r.id IS NULL OR r.status NOT IN ('queued','waiting','running') OR r.next_attempt_at>now() THEN RETURN;END IF;IF r.status='running' THEN IF r.lease_until>now() THEN RETURN;END IF;UPDATE public.site_ai_requests SET status='failed',error='Provider result uncertain after interruption. Partial text retained; no duplicate generation sent.',updated_at=now() WHERE id=_id;RETURN;END IF;IF r.deadline<now() OR NOT EXISTS(SELECT 1 FROM public.project_ai_settings WHERE project_id=r.project_id AND cloudflare_enabled) OR NOT EXISTS(SELECT 1 FROM public.ai_pool_settings WHERE id='global' AND cloudflare_pool_enabled) THEN UPDATE public.site_ai_requests SET status='failed',error='AI is off, paused, or request expired.',updated_at=now() WHERE id=_id;RETURN;END IF;RETURN QUERY UPDATE public.site_ai_requests SET status='running',lease_version=lease_version+1,lease_until=now()+interval '3 minutes',updated_at=now() WHERE id=_id RETURNING *;END $$;
CREATE FUNCTION public.reserve_site_ai(_id uuid,_version integer,_provider text,_position integer,_cost integer,_observed integer) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.site_ai_requests;u integer;v integer;e boolean;BEGIN SELECT * INTO r FROM public.site_ai_requests WHERE id=_id AND lease_version=_version AND status='running' FOR UPDATE;IF r.id IS NULL OR _cost<0 OR _cost>9500 THEN RETURN false;END IF;PERFORM pg_advisory_xact_lock(hashtextextended(_provider||r.usage_day::text,0));IF EXISTS(SELECT 1 FROM public.site_ai_key_state WHERE provider_id=_provider AND day=r.usage_day AND cooldown_until>now()) THEN RETURN false;END IF;SELECT neurons_used,exhausted INTO u,e FROM public.cloudflare_neuron_usage WHERE provider_id=_provider AND day=r.usage_day;SELECT coalesce(sum(reserved),0) INTO v FROM public.site_ai_requests WHERE provider_id=_provider AND usage_day=r.usage_day AND reserved>0;u:=greatest(coalesce(u,0),coalesce(_observed,0));IF coalesce(e,false) OR u+v>=9000 OR u+v+_cost>9500 THEN RETURN false;END IF;UPDATE public.site_ai_requests SET provider_id=_provider,key_position=_position,key_attempt=CASE WHEN provider_id=_provider THEN key_attempt+1 ELSE 1 END,attempt_serial=attempt_serial+1,reserved=_cost,updated_at=now() WHERE id=_id;RETURN true;END $$;
CREATE FUNCTION public.settle_site_ai(_id uuid,_version integer,_outcome text,_error text,_neurons integer,_delay integer) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.site_ai_requests;BEGIN SELECT * INTO r FROM public.site_ai_requests WHERE id=_id AND lease_version=_version AND status='running' FOR UPDATE;IF r.id IS NULL THEN RETURN false;END IF;IF r.provider_id IS NOT NULL THEN PERFORM pg_advisory_xact_lock(hashtextextended(r.provider_id||r.usage_day::text,0));INSERT INTO public.neuron_call_ledger(user_id,project_id,request_key,section,provider_id,key_number,model,neurons,source,action,status) VALUES(r.user_id,r.project_id,'site:'||r.id||':'||r.attempt_serial,'chat',r.provider_id,r.key_position,r.model,greatest(0,_neurons),'estimate','site_chat',_outcome);IF _outcome='quota' THEN INSERT INTO public.cloudflare_neuron_usage(provider_id,day,neurons_used,exhausted,updated_at) VALUES(r.provider_id,r.usage_day,0,true,now()) ON CONFLICT(provider_id,day) DO UPDATE SET exhausted=true,updated_at=now();END IF;IF _outcome='next' THEN INSERT INTO public.site_ai_key_state(provider_id,day,cooldown_until) VALUES(r.provider_id,r.usage_day,now()+interval '5 minutes') ON CONFLICT(provider_id,day) DO UPDATE SET cooldown_until=EXCLUDED.cooldown_until;END IF;END IF;UPDATE public.site_ai_requests SET status=CASE WHEN _outcome='complete' THEN 'completed' WHEN _outcome IN ('failed','uncertain','denied') THEN 'failed' ELSE 'waiting' END,error=_error,reserved=CASE WHEN _outcome='uncertain' THEN reserved ELSE 0 END,next_attempt_at=now()+make_interval(secs=>greatest(1,_delay)),lease_until=NULL,key_position=CASE WHEN _outcome IN ('quota','next') THEN key_position+1 ELSE key_position END,provider_id=CASE WHEN _outcome IN ('quota','next','wait') THEN NULL ELSE provider_id END,key_attempt=CASE WHEN _outcome IN ('quota','next') THEN 0 ELSE key_attempt END,updated_at=now() WHERE id=_id;RETURN true;END $$;
CREATE FUNCTION public.dispatch_site_ai(_id uuid) RETURNS bigint LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,net AS $$ DECLARE rid bigint;tok text;BEGIN SELECT token INTO tok FROM public.job_resume_config WHERE id='default';IF tok IS NULL THEN RAISE EXCEPTION 'Recovery configuration missing';END IF;SELECT net.http_post(url:='https://project--4cd30b31-2a37-4c66-9cee-ab3d574ad805.lovable.app/api/public/sites/ai/resume',headers:=jsonb_build_object('Content-Type','application/json','x-resume-token',tok),body:=jsonb_build_object('requestId',_id),timeout_milliseconds:=600000) INTO rid;RETURN rid;END $$;
CREATE FUNCTION public.disarm_site_ai_recovery() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,cron AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.site_ai_requests WHERE status IN ('queued','waiting','running') AND deadline>now()) THEN PERFORM cron.unschedule('code-haven-site-ai-recovery');END IF;END $$;
CREATE FUNCTION public.arm_site_ai_recovery() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,cron AS $$ BEGIN IF NEW.status IN ('queued','waiting','running') AND NOT EXISTS(SELECT 1 FROM cron.job WHERE jobname='code-haven-site-ai-recovery') THEN PERFORM cron.schedule('code-haven-site-ai-recovery','* * * * *',$cron$ SELECT public.dispatch_site_ai(id) FROM public.site_ai_requests WHERE (status IN ('queued','waiting') AND next_attempt_at<=now() OR status='running' AND lease_until<now()) AND deadline>now() ORDER BY next_attempt_at LIMIT 6; SELECT public.disarm_site_ai_recovery(); $cron$);END IF;RETURN NEW;END $$;
CREATE TRIGGER site_ai_recovery_on_enqueue AFTER INSERT OR UPDATE OF status ON public.site_ai_requests FOR EACH ROW EXECUTE FUNCTION public.arm_site_ai_recovery();
REVOKE ALL ON FUNCTION public.admit_site_ai(uuid,uuid,text,jsonb,text),public.claim_site_ai(uuid),public.reserve_site_ai(uuid,integer,text,integer,integer,integer),public.settle_site_ai(uuid,integer,text,text,integer,integer),public.dispatch_site_ai(uuid),public.arm_site_ai_recovery(),public.disarm_site_ai_recovery() FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.admit_site_ai(uuid,uuid,text,jsonb,text),public.claim_site_ai(uuid),public.reserve_site_ai(uuid,integer,text,integer,integer,integer),public.settle_site_ai(uuid,integer,text,text,integer,integer),public.dispatch_site_ai(uuid),public.arm_site_ai_recovery(),public.disarm_site_ai_recovery() TO service_role;